const REQ_TOPIC: &str = "RoundtripBench_Request";
const ECHO_TOPIC: &str = "RoundtripBench_Echo";
const TYPE_NAME: &str = "RoundtripBench::Roundtrip";

fn now_ns() -> u64 {
    static START: OnceLock<Instant> = OnceLock::new();
    START.get_or_init(Instant::now).elapsed().as_nanos() as u64
}

/// CPU time of the whole process, every thread of the stack included
/// (CLOCK_PROCESS_CPUTIME_ID), as bench::cpu_ns().
fn cpu_ns() -> u64 {
    let mut ts = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: clock_gettime writes the timespec it is given.
    unsafe { libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID, &mut ts) };
    ts.tv_sec as u64 * 1_000_000_000 + ts.tv_nsec as u64
}

/// Runs a future of the async API to its end on the calling thread, parking
/// it while the future waits (what the sync API of Dust does with its own
/// block_on, dds/src/std_runtime/executor.rs).
fn block_on<F: Future>(f: F) -> F::Output {
    struct Unpark(std::thread::Thread);
    impl Wake for Unpark {
        fn wake(self: Arc<Self>) {
            self.0.unpark();
        }
    }
    let waker = Waker::from(Arc::new(Unpark(std::thread::current())));
    let mut cx = Context::from_waker(&waker);
    let mut f = std::pin::pin!(f);
    loop {
        if let Poll::Ready(v) = f.as_mut().poll(&mut cx) {
            return v;
        }
        std::thread::park();
    }
}

// ------------------------------------------------------------------ QoS

/// bench::QosSpec from the same variables.
struct QosSpec {
    reliable: bool,
    keep_all: bool,
    depth: u32,
    max_samples: i64,
}

fn qos_from_env() -> QosSpec {
    let mut q = QosSpec {
        reliable: true,
        keep_all: false,
        depth: 64,
        max_samples: -1,
    };
    if let Ok(v) = std::env::var("ZERODDS_BENCH_RELIABILITY") {
        match v.as_str() {
            "besteffort" | "best_effort" | "be" => q.reliable = false,
            "reliable" => q.reliable = true,
            _ => {
                eprintln!("ZERODDS_BENCH_RELIABILITY={v} unknown");
                std::process::exit(2);
            }
        }
    }
    if let Ok(v) = std::env::var("ZERODDS_BENCH_HISTORY") {
        if v == "all" {
            q.keep_all = true;
        } else {
            match v.parse::<u32>() {
                Ok(d) if d >= 1 => q.depth = d,
                _ => {
                    eprintln!("ZERODDS_BENCH_HISTORY={v} unknown");
                    std::process::exit(2);
                }
            }
        }
    }
    if let Ok(v) = std::env::var("ZERODDS_BENCH_MAX_SAMPLES") {
        q.max_samples = v.parse().unwrap_or(-1);
    }
    q
}

fn print_qos(role: &str, q: &QosSpec) {
    let history = if q.keep_all {
        "keep_all".to_string()
    } else {
        format!("keep_last({})", q.depth)
    };
    println!(
        "qos[{role}]: reliability={} history={history} max_samples={}",
        if q.reliable { "reliable" } else { "besteffort" },
        q.max_samples
    );
}

/// The policies both endpoints set: RELIABILITY (the kind; Dust's
/// max_blocking_time stays, 100 ms), HISTORY, RESOURCE_LIMITS max_samples
/// and max_samples_per_instance as the other apps set them, and XCDR2.
struct Policies {
    reliability: ReliabilityQosPolicyKind,
    history: HistoryQosPolicyKind,
    limit: Length,
    representation: DataRepresentationQosPolicy,
}

fn policies(q: &QosSpec) -> Policies {
    Policies {
        reliability: if q.reliable {
            ReliabilityQosPolicyKind::Reliable
        } else {
            ReliabilityQosPolicyKind::BestEffort
        },
        history: if q.keep_all {
            HistoryQosPolicyKind::KeepAll
        } else {
            HistoryQosPolicyKind::KeepLast(q.depth)
        },
        limit: if q.max_samples > 0 {
            Length::Limited(q.max_samples.min(i64::from(i32::MAX)) as i32)
        } else {
            Length::Unlimited
        },
        representation: DataRepresentationQosPolicy {
            value: vec![XCDR2_DATA_REPRESENTATION],
        },
    }
}

fn writer_qos(q: &QosSpec) -> DataWriterQos {
    let p = policies(q);
    let mut qos = DataWriterQos::default();
    qos.reliability.kind = p.reliability;
    qos.history.kind = p.history;
    qos.resource_limits.max_samples = p.limit;
    qos.resource_limits.max_samples_per_instance = p.limit;
    qos.representation = p.representation;
    qos
}

fn reader_qos(q: &QosSpec) -> DataReaderQos {
    let p = policies(q);
    let mut qos = DataReaderQos::default();
    qos.reliability.kind = p.reliability;
    qos.history.kind = p.history;
    qos.resource_limits.max_samples = p.limit;
    qos.resource_limits.max_samples_per_instance = p.limit;
    qos.representation = p.representation;
    qos
}

fn domain() -> i32 {
    std::env::var("ZERODDS_BENCH_DOMAIN")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(200)
}

/// Refuses every transport but UDPv4, the one Dust DDS 0.16.0 has.
fn check_transport() {
    if let Ok(t) = std::env::var("ZERODDS_BENCH_TRANSPORT") {
        if t != "UDPv4" {
            eprintln!(
                "dust-app: ZERODDS_BENCH_TRANSPORT={t}: Dust DDS 0.16.0 has RTPS over UDPv4 only, no {t} transport"
            );
            std::process::exit(2);
        }
    }
}

fn participant() -> DomainParticipant {
    let p = DomainParticipantFactory::get_instance().create_participant(
        domain(),
        QosKind::Default,
        NO_LISTENER,
        NO_STATUS,
    );
    p.unwrap_or_else(|e| {
        eprintln!("dust-app: participant: {e:?}");
        std::process::exit(1);
    })
}

fn topic(p: &DomainParticipant, name: &str) -> Topic {
    let t = p.create_topic::<Sample>(name, TYPE_NAME, QosKind::Default, NO_LISTENER, NO_STATUS);
    t.unwrap_or_else(|e| {
        eprintln!("dust-app: topic {name}: {e:?}");
        std::process::exit(1);
    })
}

/// A publisher and its DataWriter, through the async API (the header says
/// why).
fn writer(p: &DomainParticipant, t: &Topic, qos: DataWriterQos) -> DataWriterAsync<Sample> {
    let pa = DomainParticipantAsync::from(p.clone());
    let ta = TopicAsync::from(t.clone());
    let w = block_on(async move {
        let publisher = pa
            .create_publisher(QosKind::Default, NO_LISTENER, NO_STATUS)
            .await?;
        publisher
            .create_datawriter::<Sample>(&ta, QosKind::Specific(qos), NO_LISTENER, NO_STATUS)
            .await
    });
    w.unwrap_or_else(|e| {
        eprintln!("dust-app: writer: {e:?}");
        std::process::exit(1);
    })
}

/// A subscriber and its DataReader, with the listener called on
/// DATA_AVAILABLE.
fn reader(
    p: &DomainParticipant,
    t: &Topic,
    qos: DataReaderQos,
    l: impl DataReaderListener<Sample> + Send + 'static,
) -> DataReader<Sample> {
    let r = p
        .create_subscriber(QosKind::Default, NO_LISTENER, NO_STATUS)
        .and_then(|s| {
            s.create_datareader::<Sample>(
                t,
                QosKind::Specific(qos),
                Some(l),
                &[StatusKind::DataAvailable],
            )
        });
    r.unwrap_or_else(|e| {
        eprintln!("dust-app: reader: {e:?}");
        std::process::exit(1);
    })
}

// ------------------------------------------------------------ listeners

/// The pong's listener: every valid sample back on the echo topic.
struct Echo {
    writer: DataWriterAsync<Sample>,
}

impl DataReaderListener<Sample> for Echo {
    async fn on_data_available(&mut self, the_reader: DataReaderAsync<Sample>) {
        let Ok(samples) = the_reader
            .take(
                i32::MAX,
                ANY_SAMPLE_STATE,
                ANY_VIEW_STATE,
                ANY_INSTANCE_STATE,
            )
            .await
        else {
            return;
        };
        for s in samples {
            if let (true, Some(data)) = (s.sample_info.valid_data, s.data) {
                // A write refused (KEEP_ALL at its limit, or KEEP_LAST
                // waiting longer than max_blocking_time for an
                // acknowledgment) is a lost echo, not the end.
                let _ = self.writer.write(data, None).await;
            }
        }
    }
}

/// A reader's listener that hands every valid sample to `f`.
struct OnSample<F: FnMut(&Sample) + Send + 'static> {
    f: F,
}

impl<F: FnMut(&Sample) + Send + 'static> DataReaderListener<Sample> for OnSample<F> {
    async fn on_data_available(&mut self, the_reader: DataReaderAsync<Sample>) {
        let Ok(samples) = the_reader
            .take(
                i32::MAX,
                ANY_SAMPLE_STATE,
                ANY_VIEW_STATE,
                ANY_INSTANCE_STATE,
            )
            .await
        else {
            return;
        };
        for s in &samples {
            if let (true, Some(data)) = (s.sample_info.valid_data, &s.data) {
                (self.f)(data);
            }
        }
    }
}

fn make_sample(payload: usize) -> Sample {
    Sample {
        sequence_id: 0,
        t_send_ns: 0,
        payload: vec![0xAB; payload],
    }
}

// ----------------------------------------------------------- ping / pong

fn run_pong(max_runtime_s: u64) -> i32 {
    let q = qos_from_env();
    let p = participant();
    let t_req = topic(&p, REQ_TOPIC);
    let t_echo = topic(&p, ECHO_TOPIC);
    let w = writer(&p, &t_echo, writer_qos(&q));
    let _r = reader(&p, &t_req, reader_qos(&q), Echo { writer: w });
    println!("pong: matched, listener registered");
    std::thread::sleep(Duration::from_secs(max_runtime_s));
    0
}

struct PingState {
    mu: Mutex<(u64, Vec<u64>)>,
    cv: Condvar,
    warmup: u64,
}

fn print_quantiles(rtts: &mut [u64], payload: usize) {
    if rtts.is_empty() {
        println!("no samples");
        return;
    }
    rtts.sort_unstable();
    let pct =
        |p: f64| rtts[((p * (rtts.len() - 1) as f64) as usize).min(rtts.len() - 1)] as f64 / 1000.0;
    println!(
        "payload={payload}  n={}  min={}us  p50={}us  p90={}us  p99={}us  p999={}us  max={}us",
        rtts.len(),
        rtts[0] as f64 / 1000.0,
        pct(0.50),
        pct(0.90),
        pct(0.99),
        pct(0.999),
        rtts[rtts.len() - 1] as f64 / 1000.0
    );
}

fn run_ping(payload: usize, warmup: u64, samples: u64, max_seconds: u64) -> i32 {
    let q = qos_from_env();
    let p = participant();
    let t_req = topic(&p, REQ_TOPIC);
    let t_echo = topic(&p, ECHO_TOPIC);
    let w = DataWriter::from(writer(&p, &t_req, writer_qos(&q)));
    let st = Arc::new(PingState {
        mu: Mutex::new((0, Vec::with_capacity(samples as usize))),
        cv: Condvar::new(),
        warmup,
    });
    let st2 = Arc::clone(&st);
    let on_echo = OnSample {
        f: move |s: &Sample| {
            let now = now_ns();
            let rtt = now.saturating_sub(s.t_send_ns).max(1);
            let mut g = st2.mu.lock().unwrap();
            if g.0 >= st2.warmup {
                g.1.push(rtt);
            }
            g.0 += 1;
            drop(g);
            st2.cv.notify_all();
        },
    };
    let r = reader(&p, &t_echo, reader_qos(&q), on_echo);

    // Both directions matched, at most 10 s, then 100 ms for the reliable
    // handshake, as the C++ apps wait.
    let pub_matched = || {
        w.get_publication_matched_status()
            .is_ok_and(|s| s.current_count >= 1)
    };
    let sub_matched = || {
        r.get_subscription_matched_status()
            .is_ok_and(|s| s.current_count >= 1)
    };
    let deadline = Instant::now() + Duration::from_secs(10);
    let (mut pm, mut sm) = (false, false);
    while Instant::now() < deadline {
        pm = pm || pub_matched();
        sm = sm || sub_matched();
        if pm && sm {
            break;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    if !(pm && sm) {
        eprintln!("ping: match timeout (pub={pm} sub={sm})");
    }
    std::thread::sleep(Duration::from_millis(100));

    let msg = make_sample(payload);
    let total = warmup + samples;
    let stop = if max_seconds > 0 {
        now_ns() + max_seconds * 1_000_000_000
    } else {
        0
    };
    let mut sent = 0u64;
    let mut seq = 0u64;
    while seq < total && !(stop != 0 && now_ns() >= stop) {
        let mut s = msg.clone();
        s.sequence_id = seq as u32;
        s.t_send_ns = now_ns();
        let _ = w.write(s, None);
        let g = st.mu.lock().unwrap();
        let _ = st
            .cv
            .wait_timeout_while(g, Duration::from_millis(50), |g| g.0 <= seq);
        seq += 1;
        sent += 1;
    }
    println!("ping-sent: {sent}");
    let mut g = st.mu.lock().unwrap();
    let mut rtts = std::mem::take(&mut g.1);
    drop(g);
    print_quantiles(&mut rtts, payload);
    0
}

// ------------------------------------------------------------ throughput

/// bench::TputSub.
#[derive(Default)]
struct TputSub {
    received: AtomicU64,
    inner: Mutex<TputInner>,
}

#[derive(Default)]
struct TputInner {
    bytes: u64,
    gaps: u64,
    reordered: u64,
    first_seq: u32,
    last_seq: u32,
    t_first_ns: u64,
    t_last_ns: u64,
    any: bool,
}

impl TputSub {
    fn on_sample(&self, seq: u32, len: usize) {
        let now = now_ns();
        let mut s = self.inner.lock().unwrap();
        if !s.any {
            s.any = true;
            s.first_seq = seq;
            s.last_seq = seq;
            s.t_first_ns = now;
        } else {
            let expected = s.last_seq.wrapping_add(1);
            if seq < expected {
                s.reordered += 1;
            } else {
                s.gaps += u64::from(seq - expected);
                s.last_seq = seq;
            }
        }
        s.t_last_ns = now;
        s.bytes += len as u64;
        self.received.fetch_add(1, Ordering::Relaxed);
    }
}

fn run_tput_sub(max_s: u64) -> i32 {
    let q = qos_from_env();
    print_qos("tput-sub", &q);
    let p = participant();
    let t_req = topic(&p, REQ_TOPIC);
    let st = Arc::new(TputSub::default());
    let st2 = Arc::clone(&st);
    let l = OnSample {
        f: move |s: &Sample| st2.on_sample(s.sequence_id, s.payload.len()),
    };
    let _r = reader(&p, &t_req, reader_qos(&q), l);

    // bench::tput_sub_wait_and_report, idle 2000 ms.
    let idle_ms = 2000u64;
    let t0 = now_ns();
    let limit = t0 + max_s * 1_000_000_000;
    let (mut seen, mut cpu_a, mut cnt_a, mut cpu_b, mut cnt_b, mut last_change) =
        (0u64, 0u64, 0u64, 0u64, 0u64, t0);
    let mut started = false;
    loop {
        std::thread::sleep(Duration::from_millis(20));
        let now = now_ns();
        let c = st.received.load(Ordering::Relaxed);
        if c != seen {
            let cpu = cpu_ns();
            if !started {
                started = true;
                cpu_a = cpu;
                cnt_a = c;
            }
            cpu_b = cpu;
            cnt_b = c;
            seen = c;
            last_change = now;
        } else if started && now - last_change > idle_ms * 1_000_000 {
            break;
        }
        if now >= limit {
            break;
        }
    }
    let s = st.inner.lock().unwrap();
    println!(
        "tput-sub: received={} bytes={} first_seq={} last_seq={} gaps={} reordered={} rx_window_ns={} cpu_ns={} cpu_samples={}",
        st.received.load(Ordering::Relaxed),
        s.bytes,
        s.first_seq,
        s.last_seq,
        s.gaps,
        s.reordered,
        s.t_last_ns - s.t_first_ns,
        cpu_b - cpu_a,
        cnt_b - cnt_a
    );
    0
}

fn run_tput_pub(payload: usize, seconds: u64) -> i32 {
    let q = qos_from_env();
    print_qos("tput-pub", &q);
    let p = participant();
    let t_req = topic(&p, REQ_TOPIC);
    let w = DataWriter::from(writer(&p, &t_req, writer_qos(&q)));

    // bench::tput_wait_matched: 10 s at most, then 500 ms.
    let deadline = Instant::now() + Duration::from_secs(10);
    let mut ok = false;
    while Instant::now() < deadline {
        if w.get_publication_matched_status()
            .is_ok_and(|s| s.current_count >= 1)
        {
            ok = true;
            break;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    if !ok {
        eprintln!("tput-pub: no matched reader within 10 s");
    }
    std::thread::sleep(Duration::from_millis(500));

    // bench::tput_pub_run.
    let msg = make_sample(payload);
    let (mut written, mut failed) = (0u64, 0u64);
    let mut seq = 0u32;
    let cpu0 = cpu_ns();
    let t0 = now_ns();
    let end = t0 + seconds * 1_000_000_000;
    let mut t1: u64;
    let mut i = 1u64;
    loop {
        let mut s = msg.clone();
        s.sequence_id = seq;
        let accepted = w.write(s, None).is_ok();
        if accepted {
            written += 1;
            seq = seq.wrapping_add(1);
        } else {
            failed += 1;
        }
        if !accepted || i & 15 == 0 {
            t1 = now_ns();
            if t1 >= end {
                break;
            }
        }
        i += 1;
    }
    let cpu = cpu_ns() - cpu0;
    // As the C++ apps: RELIABLE waits up to 30 s for every reader's
    // acknowledgment of what it wrote (1: all acknowledged, 0: not).
    let (mut acked, mut ack_ns) = (-1, 0u64);
    if q.reliable {
        let t = now_ns();
        acked = match w.wait_for_acknowledgments(DdsDuration::new(30, 0)) {
            Ok(()) => 1,
            Err(e) => {
                eprintln!("tput-pub: wait_for_acknowledgments: {e:?}");
                0
            }
        };
        ack_ns = now_ns() - t;
    }
    println!(
        "tput-pub: payload={payload} written={written} failed={failed} window_ns={} cpu_ns={cpu} acked={acked} ack_ns={ack_ns}",
        t1 - t0
    );
    // bench::tput_linger.
    std::thread::sleep(Duration::from_secs(2));
    0
}

// ------------------------------------------------------------------ main

fn flag(args: &[String], name: &str, default: u64) -> u64 {
    // Pairs from args[2] on, `--flag value`, as bench::parse_*_args.
    let mut i = 2;
    while i + 1 < args.len() {
        if args[i] == name {
            return args[i + 1].parse().unwrap_or(default);
        }
        i += 2;
    }
    default
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let _ = now_ns();
    check_transport();
    let code = match args.get(1).map(String::as_str) {
        Some("pong") => run_pong(args.get(2).and_then(|s| s.parse().ok()).unwrap_or(30)),
        Some("ping") => run_ping(
            flag(&args, "--payload", 64) as usize,
            flag(&args, "--warmup", 200),
            flag(&args, "--samples", 5000),
            flag(&args, "--max-seconds", 0),
        ),
        Some("tput-sub") => run_tput_sub(flag(&args, "--seconds", 5)),
        Some("tput-pub") => run_tput_pub(
            flag(&args, "--payload", 1024) as usize,
            flag(&args, "--seconds", 5),
        ),
        _ => {
            eprintln!(
                "Usage:\n  dust-roundtrip pong [max_runtime_s]\n  dust-roundtrip ping --payload N [--samples N] [--warmup N]\n  dust-roundtrip tput-sub --seconds MAX\n  dust-roundtrip tput-pub --payload N --seconds S"
            );
            2
        }
    };
    std::process::exit(code);
}
